1	// src/routing/DomainLocker.ts
2	import { SovereignDomain, classifyDomain, TOOL_DOMAIN_MAP } from '../types/SovereignDomain.js';
3	import { createLogger } from "../utils/logger.js";
4	
5	const logger = createLogger('DomainLocker');
6	
7	/**
8	 * DomainTransition — Record of domain context switches for audit trail.
9	 */
10	export interface DomainTransition {
11	    readonly from: SovereignDomain | null;
12	    readonly to: SovereignDomain;
13	    readonly intent: string;
14	    readonly timestamp: number;
15	}
16	
17	/**
18	 * DispatchVerdict — Result of a tool dispatch check.
19	 * Replaces the old hard-block model with wait/pass:
20	 *   PASS  — tool is in the active domain, execute immediately
21	 *   WAIT  — tool is cross-domain, Kimi dispatches to a worker and waits for return
22	 */
23	export type DispatchVerdict = {
24	    readonly action: 'PASS' | 'WAIT';
25	    readonly toolDomain: SovereignDomain | 'UNKNOWN';
26	    readonly activeDomain: SovereignDomain | null;
27	    readonly reasoning: string;
28	};
29	
30	/**
31	 * DomainViolationError — Kept for backwards compatibility but only thrown
32	 * for explicitly dangerous operations (reserved for future use).
33	 */
34	export class DomainViolationError extends Error {
35	    public readonly toolName: string;
36	    public readonly requiredDomain: SovereignDomain;
37	    public readonly activeDomain: SovereignDomain;
38	
39	    constructor(toolName: string, requiredDomain: SovereignDomain, activeDomain: SovereignDomain) {
40	        super(`DOMAIN VIOLATION: Tool "${toolName}" requires ${requiredDomain}, active is ${activeDomain}.`);
41	        this.name = 'DomainViolationError';
42	        this.toolName = toolName;
43	        this.requiredDomain = requiredDomain;
44	        this.activeDomain = activeDomain;
45	    }
46	}
47	
48	export class ToolAuthorizationError extends Error {
49	    constructor(
50	        public readonly modelId: string,
51	        public readonly toolName: string,
52	        public readonly authorizedTools: readonly string[]
53	    ) {
54	        super(`Tool authorization failed: Model ${modelId} not authorized for ${toolName}.`);
55	        this.name = 'ToolAuthorizationError';
56	    }
57	}
58	
59	/**
60	 * DomainLocker — Wait/Pass Dispatch Model.
61	 *
62	 * Kimi is the orchestrating agent. It classifies domain, dispatches tools
63	 * to the right worker, waits for their output, and passes it back.
64	 *
65	 * Rules:
66	 * 1. Every task is classified into a domain for routing context.
67	 * 2. Same-domain tools get PASS (immediate execution).
68	 * 3. Cross-domain tools get WAIT (Kimi dispatches to a domain worker).
69	 * 4. No hard blocks. Kimi is the brain — it can reach any limb.
70	 * 5. All transitions are logged for audit.
71	 */
72	export class DomainLocker {
73	    private activeDomain: SovereignDomain | null = null;
74	    private readonly transitionHistory: DomainTransition[] = [];
75	    private lockDepth = 0;
76	
77	    /**
78	     * Set the domain context for a task. Not a "lock" — just context.
79	     */
80	    public lockDomain(intent: string): DomainTransition {
81	        const previousDomain = this.activeDomain;
82	        const newDomain = classifyDomain(intent);
83	
84	        this.activeDomain = newDomain;
85	        this.lockDepth++;
86	
87	        const transition: DomainTransition = {
88	            from: previousDomain,
89	            to: newDomain,
90	            intent: intent.substring(0, 120),
91	            timestamp: Date.now()
92	        };
93	
94	        this.transitionHistory.push(transition);
95	
96	        logger.info({
97	            from: previousDomain,
98	            to: newDomain,
99	            lockDepth: this.lockDepth,
100	            intent: intent.substring(0, 80)
101	        }, 'Domain context set');
102	
103	        return transition;
104	    }
105	
106	    /**
107	     * Force-set a specific domain context (sensory interception / manual override).
108	     */
109	    public forceLock(domain: SovereignDomain, reason: string): DomainTransition {
110	        const previousDomain = this.activeDomain;
111	        this.activeDomain = domain;
112	        this.lockDepth++;
113	
114	        const transition: DomainTransition = {
115	            from: previousDomain,
116	            to: domain,
117	            intent: `[FORCE] ${reason}`,
118	            timestamp: Date.now()
119	        };
120	
121	        this.transitionHistory.push(transition);
122	        logger.info({ from: previousDomain, to: domain, reason }, 'Domain force-set');
123	
124	        return transition;
125	    }
126	
127	    /**
128	     * Release the current domain context.
129	     */
130	    public releaseDomain(): void {
131	        if (this.lockDepth > 0) {
132	            this.lockDepth--;
133	        }
134	        if (this.lockDepth === 0) {
135	            logger.info({ releasedDomain: this.activeDomain }, 'Domain context released');
136	            this.activeDomain = null;
137	        }
138	    }
139	
140	    /**
141	     * Complete reset of domain state to prevent cross-contamination between commands.
142	     */
143	    public forceReleaseAll(): void {
144	        if (this.lockDepth > 0 || this.activeDomain !== null) {
145	            logger.info({ releasedDomain: this.activeDomain, clearedDepth: this.lockDepth }, 'Domain context forcefully reset for new command isolation');
146	            this.activeDomain = null;
147	            this.lockDepth = 0;
148	        }
149	    }
150	
151	    /**
152	     * Dispatch check — returns PASS or WAIT instead of blocking.
153	     * Kimi uses this to decide whether to execute directly or dispatch to a worker.
154	     */
155	    public dispatchCheck(toolName: string): DispatchVerdict {
156	        const toolDomain = (TOOL_DOMAIN_MAP[toolName] ?? 'UNKNOWN') as SovereignDomain | 'UNKNOWN';
157	
158	        // No active domain context — pass everything
159	        if (this.activeDomain === null) {
160	            return { action: 'PASS', toolDomain, activeDomain: null, reasoning: 'No domain context — open dispatch' };
161	        }
162	
163	        // Same domain — immediate pass
164	        if (toolDomain === this.activeDomain) {
165	            return { action: 'PASS', toolDomain, activeDomain: this.activeDomain, reasoning: `Tool in active domain (${this.activeDomain})` };
166	        }
167	
168	        // Cross-domain — Kimi dispatches to the right worker and waits
169	        logger.info({ tool: toolName, toolDomain, activeDomain: this.activeDomain }, 'Cross-domain dispatch — Kimi routing to worker');
170	        return {
171	            action: 'WAIT',
172	            toolDomain,
173	            activeDomain: this.activeDomain,
174	            reasoning: `Cross-domain: ${toolDomain} tool in ${this.activeDomain} context — dispatching to worker`
175	        };
176	    }
177	
178	    /**
179	     * Legacy compatibility — isToolAllowed always returns true now.
180	     * Kimi can reach any limb.
181	     */
182	    public isToolAllowed(_toolName: string): boolean {
183	        return true;
184	    }
185	
186	    /**
187	     * Legacy compatibility — assertToolAllowed is now a no-op.
188	     * Use dispatchCheck() for routing decisions instead.
189	     */
190	    public assertToolAllowed(_toolName: string): void {
191	        // Wait/pass model: never blocks. Kimi is the brain.
192	    }
193	
194	    public getActiveDomain(): SovereignDomain | null {
195	        return this.activeDomain;
196	    }
197	
198	    public getAllowedDomains(): ReadonlySet<SovereignDomain> {
199	        // All domains are reachable — Kimi dispatches, workers execute
200	        return new Set(Object.values(SovereignDomain));
201	    }
202	
203	    public getTransitionHistory(): readonly DomainTransition[] {
204	        return this.transitionHistory;
205	    }
206	
207	    public getLockDepth(): number {
208	        return this.lockDepth;
209	    }
210	}
