1	import { createLogger } from '../utils/logger.js';
2	import { type WorldDelta, type ReconciliationResult, type Result, ok, err } from '../core/models.js';
3	import { SubstrateResolver } from '../engines/gameplay/SubstrateResolver.js';
4	import { readFileSync, existsSync } from 'fs';
5	import { join } from 'path';
6	
7	const logger = createLogger('GlobeReconciliationKernel');
8	
9	/**
10	 * GlobeReconciliationKernel
11	 * 
12	 * Job: Distributed Belief Reconciliation Surface.
13	 * Merges ms_x_y chunks with live CNS deltas to produce a unified,
14	 * uncertainty-aware world view for the Globe perception layer.
15	 */
16	export class GlobeReconciliationKernel {
17	    private static instance: GlobeReconciliationKernel | undefined;
18	    
19	    // Memory-mapped belief state (ms_x_y.json chunks)
20	    private beliefCache: Map<string, any> = new Map();
21	    private activeDeltas: Map<string, WorldDelta[]> = new Map();
22	    
23	    private readonly UNCERTAINTY_THRESHOLD = 0.4;
24	
25	    public static getInstance(): GlobeReconciliationKernel {
26	        if (!this.instance) this.instance = new GlobeReconciliationKernel();
27	        return this.instance;
28	    }
29	
30	    private constructor() {}
31	
32	    /**
33	     * ingestDelta - Push a live mutation into the reconciliation surface.
34	     */
35	    public ingestDelta(delta: WorldDelta): void {
36	        const key = `${delta.x},${delta.y},${delta.z}`;
37	        const deltas = this.activeDeltas.get(key) || [];
38	        deltas.push(delta);
39	        
40	        // Keep only recent deltas (Phase 81: Temporal pruning)
41	        if (deltas.length > 5) deltas.shift();
42	        
43	        this.activeDeltas.set(key, deltas);
44	        logger.debug({ key, type: delta.type, source: delta.source }, 'Delta ingested into reconciliation surface');
45	    }
46	
47	    /**
48	     * reconcileTile - Calculate the authoritative state of a single tile.
49	     * Compares CNS decisions against historical belief and static cache definitions.
50	     */
51	    public async reconcileTile(x: number, y: number, z: number): Promise<ReconciliationResult> {
52	        const key = `${x},${y},${z}`;
53	        const deltas = this.activeDeltas.get(key) || [];
54	        const belief = await this.getBeliefAt(x, y, z);
55	        
56	        // 1. Identify layers
57	        const layers: Array<{ source: string; value: string; confidence: number }> = [];
58	        
59	        // Layer: Static Cache (via ms_x_y)
60	        if (belief) {
61	            layers.push({
62	                source: "CACHE",
63	                value: belief.type === 'object' ? 'BLOCKED' : 'WALKABLE',
64	                confidence: 0.9 // High confidence in static geometry
65	            });
66	        }
67	
68	        // Layer: CNS decisions (POG2)
69	        const cnsDeltas = deltas.filter(d => d.source === "POG2");
70	        if (cnsDeltas.length > 0) {
71	            const latest = cnsDeltas[cnsDeltas.length - 1];
72	            layers.push({
73	                source: "POG2",
74	                value: latest.type,
75	                confidence: latest.confidence
76	            });
77	        }
78	
79	        // 2. Determine Consensus & Uncertainty
80	        let consensus: ReconciliationResult['consensus'] = "STABLE";
81	        let uncertainty = 0;
82	        let primarySource: ReconciliationResult['primarySource'] = "CACHE";
83	
84	        if (layers.length > 1) {
85	            const p2 = layers.find(l => l.source === "POG2");
86	            const cache = layers.find(l => l.source === "CACHE");
87	
88	            if (p2 && cache && p2.value !== cache.value) {
89	                // Conflict detected: CNS disagrees with Cache
90	                consensus = "INSTABILITY_FIELD";
91	                uncertainty = 1.0 - Math.min(p2.confidence, cache.confidence);
92	                primarySource = "POG2"; // CNS is authoritative
93	            }
94	        } else if (layers.length === 1) {
95	            primarySource = layers[0].source as any;
96	        }
97	
98	        return {
99	            tile: { x, y, z },
100	            consensus,
101	            primarySource,
102	            uncertainty,
103	            layers
104	        };
105	    }
106	
107	    /**
108	     * getBeliefAt - Retrieve the best guess of reality from the ms_x_y chunks.
109	     */
110	    private async getBeliefAt(x: number, y: number, z: number): Promise<any | null> {
111	        const rx = Math.floor(x / 64);
112	        const ry = Math.floor(y / 64);
113	        const chunkKey = `ms_${rx}_${ry}`;
114	
115	        let chunk = this.beliefCache.get(chunkKey);
116	        if (!chunk) {
117	            chunk = await this.loadChunk(rx, ry);
118	            if (chunk) this.beliefCache.set(chunkKey, chunk);
119	        }
120	
121	        if (!chunk) return null;
122	
123	        // Find entity on this tile
124	        return chunk.entities.find((e: any) => e.x === x && e.y === y && e.z === z) || null;
125	    }
126	
127	    private async loadChunk(rx: number, ry: number): Promise<any | null> {
128	        const path = join(process.cwd(), 'public', 'unified', `ms_${rx}_${ry}.json`);
129	        if (!existsSync(path)) return null;
130	
131	        try {
132	            const data = readFileSync(path, 'utf8');
133	            return JSON.parse(data);
134	        } catch (e) {
135	            logger.error({ rx, ry, error: (e as Error).message }, 'Failed to load belief chunk');
136	            return null;
137	        }
138	    }
139	}
