74	            lineIndex: (this.lines.length % 6) + 1,
75	            title: 'Sovereign Synthesis',
76	            content,
77	            state: YaoState.YoungMixed,
78	            importance: 1
79	        });
80	    }
81	    private static instance: HexagramManager | undefined;
82	    private static mode: 'production' | 'mock' = 'production';
83	    private lines: ContextCard[] = [];
84	    private readonly projectId: string;
85	
86	    public static getInstance(): HexagramManager {
87	        if (!HexagramManager.instance) {
88	            throw new Error('HexagramManager not initialized.');
89	        }
90	        return HexagramManager.instance;
91	    }
92	
93	    public static initializeMock(): void {
94	        HexagramManager.mode = 'mock';
95	        // Create a minimal mock instance that doesn't require a vectorDB
96	        if (!HexagramManager.instance) {
97	            HexagramManager.instance = new HexagramManager(null, 'mock-project');
98	        }
99	    }
100	
101	    public static isMock(): boolean {
102	        return HexagramManager.mode === 'mock';
103	    }
104	
105	    public static resetInstance(): void {
106	        if (process.env.NODE_ENV === 'production') {
107	            throw new Error('resetInstance is forbidden in production');
108	        }
109	        HexagramManager.instance = undefined;
110	        HexagramManager.mode = 'production';
111	    }
112	
113	    public updateState(sensors: any): void {
114	        // Integrate somatic sensory feedback into the thought processor
115	    }
116	
117	    /**
118	     * setYaoState - Direct state transformation override.
119	     * Pulse-governed nodes use this to force the organism into specific metabolic states.
120	     */
121	    public setYaoState(state: YaoState): void {
122	        // In the existing architecture, the state is derived from the lines.
123	        // To "set" the state, we inject a high-priority "Pulse" card that dominates the derivation.
124	        this.pushLine({
125	            lineIndex: 2, // Biological Pulse / System Vitality
126	            title: 'Substrate Health Pulse',
