132	
133	    public healthCheck(): { online: boolean; details: string } {
134	        return { online: true, details: 'I Ching Router Online' };
135	    }
136	
137	    /**
138	     * getTransitionalState — Computes the full transitional topology from
139	     * GhostSplat field metrics and kernel diagnostics.
140	     */
141	    public getTransitionalState(
142	        field: GhostSplatField,
143	        diagnostics: KernelDiagnostics
144	    ): TransitionalState {
145	        const movingLines = this.detectMovingLines(field, diagnostics);
146	        const primaryHex = this.getCurrentHexagram();
147	        const futureHex = this.computeFutureHexagram(primaryHex, movingLines);
148	        const nuclearHex = this.computeNuclearHexagram(primaryHex);
149	
150	        return {
151	            primary: primaryHex,
152	            future: futureHex,
153	            nuclear: nuclearHex,
154	            movingLines,
155	            transitionProgress: this.computeTransitionProgress(diagnostics, movingLines),
156	            energyFlow: this.detectEnergyFlow(field),
157	            falseStability: this.detectFalseStability(movingLines, diagnostics)
158	        };
159	    }
160	
161	    private detectMovingLines(
162	        field: GhostSplatField,
163	        diag: KernelDiagnostics
164	    ): MovingLine[] {
165	        const lines: MovingLine[] = [];
166	        const now = CanonicalClock.getInstance().simulatedNow();
167	
168	        // ── Line 1: Cache Substrate Health (internal) ──
169	        const cacheTime = diag.cacheParseTime || 0;
170	        const cacheTrend = diag.cacheParseTimeTrend || 0;
171	        if (cacheTime > LINE_THRESHOLDS[1].danger) {
172	            lines.push({ position: 1, fromState: 'YANG', toState: 'YIN', confidence: Math.min(1.0, cacheTime / 200), source: 'CacheForensicsLimb', timestamp: now });
173	        } else if (cacheTime < LINE_THRESHOLDS[1].recovery && cacheTrend < 0) {
174	            lines.push({ position: 1, fromState: 'YIN', toState: 'YANG', confidence: Math.min(1.0, Math.abs(cacheTrend)), source: 'CacheForensicsLimb', timestamp: now });
175	        }
176	
177	        // ── Line 2: NPC Prediction Confidence (intuitive) ──
178	        const npcConf = this.computeAvgConfidence(field.projections, 'npc_');
179	        if (npcConf < LINE_THRESHOLDS[2].danger) {
180	            lines.push({ position: 2, fromState: 'YANG', toState: 'YIN', confidence: 1.0 - npcConf, source: 'GhostSplatEngine', timestamp: now });
181	        } else if (npcConf > LINE_THRESHOLDS[2].recovery) {
182	            lines.push({ position: 2, fromState: 'YIN', toState: 'YANG', confidence: npcConf, source: 'GhostSplatEngine', timestamp: now });
183	        }
184	
185	        // ── Line 3: Combat Threat Density (conscious activity) ──
186	        const threatDensity = this.computeThreatDensity(field);
187	        if (threatDensity > LINE_THRESHOLDS[3].danger) {
188	            lines.push({ position: 3, fromState: 'YIN', toState: 'YANG', confidence: Math.min(1.0, threatDensity), source: 'CombatRotationEngine', timestamp: now });
189	        } else if (threatDensity < LINE_THRESHOLDS[3].recovery) {
190	            lines.push({ position: 3, fromState: 'YANG', toState: 'YIN', confidence: 1.0 - threatDensity, source: 'CombatRotationEngine', timestamp: now });
191	        }
192	
193	        // ── Line 4: Player Projection Drift (outer engagement) ──
194	        const playerDrift = this.computePlayerDrift(field);
195	        if (playerDrift > LINE_THRESHOLDS[4].danger) {
196	            lines.push({ position: 4, fromState: 'YANG', toState: 'YIN', confidence: Math.min(1.0, playerDrift / 5), source: 'PlayerAgent', timestamp: now });
197	        }
198	
199	        // ── Line 5: NecromancerBrain Prediction (mastery) ──
200	        const predTimeout = diag.necromancerLatency || 0;
201	        if (predTimeout > LINE_THRESHOLDS[5].danger) {
202	            lines.push({ position: 5, fromState: 'YANG', toState: 'YIN', confidence: Math.min(1.0, predTimeout / 1000), source: 'NecromancerBrain', timestamp: now });
203	        }
204	
205	        // ── Line 6: Tick Completion (culmination) ──
206	        const overrun = Math.max(0, (diag.lastTickDuration || 0) - 600);
207	        if (overrun > LINE_THRESHOLDS[6].danger) {
208	            lines.push({ position: 6, fromState: 'YANG', toState: 'YIN', confidence: Math.min(1.0, overrun / 200), source: 'TemporalHeartbeatLimb', timestamp: now });
209	        }
210	
211	        return lines;
212	    }
213	
214	    private computeAvgConfidence(projections: Map<string, EntityGhost>, prefix: string): number {
215	        let total = 0, count = 0;
216	        projections.forEach((ghost, id) => {
217	            if (id.startsWith(prefix)) {
218	                total += ghost.confidence;
219	                count++;
220	            }
221	        });
222	        return count > 0 ? total / count : 1.0;
223	    }
224	
225	    private computeThreatDensity(field: GhostSplatField): number {
226	        let hotTiles = 0;
227	        for (let i = 0; i < field.heatmap.length; i++) {
228	            if (field.heatmap[i] > 0) hotTiles++;
229	        }
230	        return hotTiles / (66 * 66);
231	    }
232	
233	    private computePlayerDrift(field: GhostSplatField): number {
234	        const playerGhost = Array.from(field.projections.values()).find(g => g.entityId.startsWith('player_'));
235	        if (!playerGhost) return 0;
236	        return playerGhost.confidence < 0.5 ? 5 : 0;
237	    }
238	
239	    private computeTransitionProgress(diag: KernelDiagnostics, movingLines: MovingLine[]): number {
240	        const tickElapsed = diag.tickElapsedMs || 0;
241	        const volatility = diag.volatilityEMA || 0;
242	        const timeProgress = Math.min(1.0, tickElapsed / 300); // 300ms POG2 cycle
243	        const volatilityBoost = volatility * 0.3;
244	        const lineBoost = (movingLines.length / 6) * 0.2;
245	        return Math.min(1.0, timeProgress + volatilityBoost + lineBoost);
