6	export interface ScheduledTask<T> {
7	    id: string;
8	    priority: number;
9	    provider: string;
10	    execute: () => Promise<T>;
11	    timeoutMs: number;
12	    submittedAt: number;
13	    resolve: (value: T | PromiseLike<T>) => void;
14	    reject: (reason?: any) => void;
15	}
16	
17	const PROVIDER_LIMITS: Record<string, number> = {
18	    ollama: 1,      // Local models are strictly serial to avoid VRAM thrashing
19	    gemini: 10,     // Cloud APIs can handle more concurrency
20	    cloudflare: 5,
21	    fireworks: 8,
22	    openrouter: 10,
23	    huggingface: 3,
24	    pipeline: 1,    // Production runs are heavy; keep at 1 to prevent resource starvation
25	    vision: 1       // Puppeteer instances are resource-heavy
26	};
27	
28	/**
29	 * TaskScheduler - Non-blocking priority orchestrator for the Sovereign CNS.
30	 * Prevents slow local models from stalling the entire nervous system.
31	 */
32	export class TaskScheduler {
33	    private queue: ScheduledTask<any>[] = [];
34	    private activeCount: Map<string, number> = new Map();
35	    private waitTimes: Map<string, number[]> = new Map(); // Rolling window of last 10 wait times
36	    private readonly WINDOW_SIZE = 10;
37	    private queueDepthPeak = 0;
38	    private completedTasks = 0;
39	    private taskCounter = 0;
40	    private readonly startTime = Date.now();
41	    private static instance: TaskScheduler;
42	
43	    private constructor() {}
44	
45	    public static getInstance(): TaskScheduler {
46	        if (!TaskScheduler.instance) {
47	            TaskScheduler.instance = new TaskScheduler();
48	        }
49	        return TaskScheduler.instance;
50	    }
51	
52	    /**
53	     * Map YaoState to numeric priority.
54	     * OldYang (Evolution/Stability) = 4
55	     * YoungYang (Action) = 3
56	     * YoungYin (Stability) = 2
57	     * OldYin (Refinement) = 1
58	     */
59	    public static mapPriority(state: YaoState): number {
60	        const priorityMap: Record<number, number> = {
61	            3: 4, // OldYang (Change/Highest)
62	            2: 3, // YoungYang (Stable/Action)
63	            0: 2, // YoungYin (Stable/Stability)
64	            1: 1, // OldYin (Change/Refinement)
65	            4: 4, // OldMixed (Chaotic/High)
66	            5: 2  // YoungMixed (Emerging/Low)
67	        };
68	        return priorityMap[state] || 2;
69	    }
70	
71	    /**
72	     * Schedule a task for execution.
73	     * Returns a promise that resolves when the task is complete.
74	     */
75	    public async schedule<T>(
76	        provider: string,
77	        priority: number,
78	        execute: () => Promise<T>,
79	        timeoutMs: number = 60000
80	    ): Promise<T> {
81	        const id = `task-${++this.taskCounter}-${Math.random().toString(36).substring(7)}`;
82	        
83	        return new Promise<T>((resolve, reject) => {
84	            const task: ScheduledTask<T> = {
85	                id,
86	                priority,
87	                provider,
88	                execute,
89	                timeoutMs,
90	                submittedAt: Date.now(),
91	                resolve,
92	                reject
93	            };
94	
95	            this.queue.push(task);
96	            this.sortQueue();
97	            
98	            if (this.queue.length > this.queueDepthPeak) {
99	                this.queueDepthPeak = this.queue.length;
100	            }
101	
102	            if (this.queue.length > 25) {
103	                logger.warn({ queueSize: this.queue.length }, 'CNS Congestion Detected: Queue depth exceeds threshold');
104	            }
105	            
106	            logger.debug({ id, provider, priority, queueSize: this.queue.length }, 'Task scheduled');
107	            
108	            this.processQueue();
109	        });
110	    }
111	
112	    private sortQueue(): void {
113	        // Sort by priority (desc) then by submission time (asc)
114	        this.queue.sort((a, b) => {
115	            if (b.priority !== a.priority) return b.priority - a.priority;
116	            return a.submittedAt - b.submittedAt;
117	        });
118	    }
119	
120	    private async processQueue(): Promise<void> {
121	        if (this.queue.length === 0) return;
122	
123	        for (let i = 0; i < this.queue.length; i++) {
124	            const task = this.queue[i];
125	            const currentActive = this.activeCount.get(task.provider) || 0;
126	            const limit = PROVIDER_LIMITS[task.provider] || 2;
127	
128	            if (currentActive < limit) {
129	                // Remove from queue and start execution
130	                this.queue.splice(i, 1);
131	                
132	                // Track wait time
133	                const waitTime = Date.now() - task.submittedAt;
134	                const times = this.waitTimes.get(task.provider) || [];
135	                times.push(waitTime);
136	                if (times.length > this.WINDOW_SIZE) times.shift();
137	                this.waitTimes.set(task.provider, times);
138	
139	                const avgWait = times.reduce((a, b) => a + b, 0) / times.length;
140	                if (avgWait > 2000) {
141	                    logger.warn({ provider: task.provider, avgWait }, 'CNS Congestion Signal: High provider wait time detected');
142	                }
143	
144	                this.runTask(task);
145	                i--; // Adjust index after splice
146	            }
147	        }
148	    }
149	
150	    private async runTask<T>(task: ScheduledTask<T>): Promise<void> {
151	        const provider = task.provider;
152	        this.activeCount.set(provider, (this.activeCount.get(provider) || 0) + 1);
153	
154	        let finished = false;
155	        const releaseLane = () => {
156	            if (finished) return;
157	            finished = true;
158	            this.activeCount.set(provider, (this.activeCount.get(provider) || 1) - 1);
159	            // Process queue again to pick up new tasks
160	            setImmediate(() => this.processQueue());
161	        };
162	
163	        // Sovereign Gate: High-fidelity narrative synthesis may take hours/days.
164	        // We expand the hard timeout to 24 hours (86,400,000ms) for Executive/Master tier tasks (priority <= 2).
165	        const absoluteTimeout = (task.priority <= 2) ? 86_400_000 : task.timeoutMs;
166	
167	        const timeoutId = setTimeout(() => {
168	            if (!finished) {
169	                logger.error({ id: task.id, provider, absoluteTimeout }, `Task exceeded hard timeout (${absoluteTimeout}ms) - rejecting`);
170	                task.reject(new Error(`Task ${task.id} timed out after ${absoluteTimeout}ms`));
171	            }
172	        }, absoluteTimeout);
173	
174	        try {
175	            logger.debug({ id: task.id, provider }, 'Task starting execution');
176	            const result = await task.execute();
177	            clearTimeout(timeoutId);
178	            if (!finished) {
179	                this.completedTasks++;
180	                task.resolve(result);
181	            }
182	        } catch (err) {
183	            clearTimeout(timeoutId);
184	            if (!finished) {
185	                logger.error({ id: task.id, provider, error: (err as Error).message }, 'Task execution failed');
186	                task.reject(err);
187	            }
188	        } finally {
189	            releaseLane();
190	        }
191	    }
192	
193	    /** Status for diagnostics */
194	    public getQueueStatus() {
195	        const providerBacklog: Record<string, number> = {};
196	        for (const task of this.queue) {
197	            providerBacklog[task.provider] = (providerBacklog[task.provider] || 0) + 1;
198	        }
199	
200	        const avgWaitTimes: Record<string, number> = {};
201	        for (const [provider, times] of this.waitTimes.entries()) {
202	            avgWaitTimes[provider] = Math.round(times.reduce((a, b) => a + b, 0) / times.length);
203	        }
204	
205	        return {
206	            totalPending: this.queue.length,
207	            queueDepthPeak: this.queueDepthPeak,
208	            effectiveThroughput: Number((this.completedTasks / ((Date.now() - this.startTime) / 1000)).toFixed(2)),
209	            providerBacklog,
210	            activeCount: Object.fromEntries(this.activeCount),
211	            avgWaitTimesMs: avgWaitTimes,
212	            limits: PROVIDER_LIMITS
213	        };
214	    }
215	}
