282	    /**
283	     * Classify prompt complexity and intent.
284	     */
285	    async classify(prompt: string): Promise<RoutingComplexity> {
286	        if (COMPLEXITY_KEYWORDS.Chromanumber.test(prompt)) return 'Chromanumber';
287	        if (COMPLEXITY_KEYWORDS.SovereignEye.test(prompt)) return 'SovereignEye';
288	        if (COMPLEXITY_KEYWORDS.Vision.test(prompt)) return 'Vision';
289	        if (COMPLEXITY_KEYWORDS.Voice.test(prompt)) return 'Voice';
290	        if (COMPLEXITY_KEYWORDS.Orchestrator.test(prompt)) return 'Orchestrator';
291	
292	        // Standard code complexity scoring...
293	        const wordCount = prompt.split(/\s+/).length;
294	        const codeDensity = (prompt.match(/\b(function|class|const|interface|type|async|await|import|export)\b/g) || []).length;
295	
296	        let score = 0;
297	
298	        // Phase 85: Ignore-Aware Routing
299	        // If the prompt refers to ignored paths, it's likely a trivial or "Yin" request.
300	        const systemRoot = getSovereignRoot();
301	        const pathMatches = prompt.match(/[a-zA-Z0-9._/-]+/g) || [];
302	        for (const p of pathMatches) {
303	            if (p.includes('/') && SovereignIgnoreManager.isIgnored(systemRoot, p)) {
304	                score -= 2; // Significant penalty for focusing on boilerplate
305	            }
306	        }
307	
308	        if (wordCount > 80) score += 2;
309	        if (codeDensity > 5) score += 2;
310	        if (COMPLEXITY_KEYWORDS.Yang.test(prompt)) score += 3;
311	        else if (COMPLEXITY_KEYWORDS.YinYang.test(prompt)) score += 1;
312	        else if (COMPLEXITY_KEYWORDS.Yin.test(prompt)) score -= 1;
313	
314	        if (score >= 4) return 'Yang';
315	        if (score >= 1) return 'YinYang';
316	        return 'Yin';
317	    }
