333	            // Use the absolute cheapest fast model available in the system
334	            const triageModel = this.config.fastPathModel || 'deepseek-r1:8b'; 
335	            
336	            // Bypass the router itself (prevent infinite loops) by calling the provider directly, 
337	            // or we configure ModelClient to allow a direct model override.
338	            // For now, we simulate the structure.
339	            const classificationPrompt = `Classify this task exactly into one of these words: [simple, complex, vision, coding, embedding, orchestration]. Task: ${prompt.substring(0, 500)}`;
340	            
341	            const result = await this.modelClient.call({
342	                model: triageModel,
343	                prompt: classificationPrompt,
344	                maxTokens: 20,
345	                temperature: 0.1,
346	                isSystemPulse: true // Phase 8.2: Prevent triage from poisoning reputation
347	            });
348	            
349	            if (!result.ok) {
350	                this.lastConfidence = 0.3;
351	                return 'text';
352	            }
353	
354	            const response = result.value.response.toLowerCase();
355	            if (response.includes('trivial')) {
356	                this.lastConfidence = 0.9;
357	                return 'text';
358	            }
359	            if (response.includes('simple')) {
360	                this.lastConfidence = 0.7;
361	                return 'text';
362	            }
363	            if (response.includes('complex') || response.includes('coding')) {
364	                this.lastConfidence = 0.5;
365	                return 'text';
366	            }
367	            if (response.includes('vision')) {
368	                this.lastConfidence = 0.7; // Vision is usually specific and well-defined
369	                return 'vision';
370	            }
371	            if (response.includes('embedding')) {
372	                this.lastConfidence = 0.9;
373	                return 'embedding';
374	            }
375	            
376	            this.lastConfidence = 0.3;
377	            return 'text'; 
378	        } catch (err) {
379	            logger.debug({ err }, 'Dynamic classification failed, falling back to heuristic text route');
380	            return 'text';
