718	    private sortModelsBySovereignPriority(models: string[]): string[] {
719	        if (models.length === 0) return [];
720	        const unique = Array.from(new Set(models.filter(Boolean)));
721	        
722	        // The first model is considered the "preferred" target, keep it at [0] if it's healthy/available
723	        const preferred = unique[0];
724	        const rest = unique.slice(1);
725	
726	        const local: string[] = [];
727	        const cloudflareHf: string[] = [];
728	        const others: string[] = [];
729	
730	        for (const m of rest) {
731	            if (m.startsWith('huggingface:') || m.startsWith('@cf/') || m.includes('cloudflare') || m.startsWith('fireworks:') || m.startsWith('openrouter:')) {
732	                cloudflareHf.push(m);
733	            } else if (m.startsWith('gemini:') || m.includes('openai') || m.includes('anthropic') || m.includes(':cloud')) {
734	                others.push(m);
735	            } else {
736	                // Determine via omission: Ollama / Local Substrate
737	                local.push(m);
738	            }
739	        }
740	
741	        // Optimal Cloud-First/Local-Fallback: 
742	        // 1. Preferred target
743	        // 2. Other Clouds / APIs
744	        // 3. Local Substrate
745	        // 4. Guaranteed universal Local Fallback
746	        const result = [preferred, ...others, ...cloudflareHf, ...local];
747	        
748	        // Ensure the absolute sovereign local fallback is pushed to the very end if not already
749	        const finalFallback = this.config.localFallbackModel;
750	        const fallbackFiltered = result.filter(m => m !== finalFallback);
751	        fallbackFiltered.push(finalFallback);
752	
753	        return Array.from(new Set(fallbackFiltered));
754	    }
