768	    private findWorkingModel(preferred: string, fallbacks: string[], taskType: TaskType = 'text'): string {
769	        const rawList = [preferred, ...fallbacks, this.config.localFallbackModel];
770	        const unique = Array.from(new Set(rawList.filter(Boolean)));
771	        
772	        // ðŸ§¬ Nervous System v2: Scored Routing (Phase 9)
773	        const allModels = this.rolodex?.getAllModels() || [];
774	        const scored = unique
775	            .filter(mId => this.isModelAvailableAndHealthy(mId) && this.isModalityCompatible(mId, taskType))
776	            .map(mId => {
777	                // Find matching model in rolodex
778	                const mData = allModels.find(m => m.id === mId || `${m.provider}:${m.id}` === mId);
779	                const rep = mData?.reputation ?? 1.0;
780	                const avgLatency = mData?.avgLatencyMs ?? 500;
781	                const expectedLatency = Math.max(avgLatency, 50);
782	                
783	                // ðŸ§¬ Phase 108: Explicit Decision Weighting
784	                // score = (reputation weight) / log(1 + latency)
785	                const score = rep / Math.log(1 + expectedLatency);
786	                return { id: mId, score };
787	            })
788	            .sort((a, b) => b.score - a.score);
789	
790	        const sorted = scored.map(s => s.id);
791	        if (sorted.length === 0) return this.config.localFallbackModel;
792	
793	        // ðŸ§¬ Nervous System v2: Îµ-greedy Adaptive Exploration (Phase 9)
794	        const epsilon = 0.25 - (this.lastConfidence * 0.20);
795	        if (Math.random() < epsilon && sorted.length > 1) {
796	            const randomIndex = Math.floor(Math.random() * (sorted.length - 1)) + 1; // Pick non-primary
797	            const exploredModel = sorted[randomIndex];
798	            logger.info({ model: exploredModel, epsilon, taskType }, 'ðŸ§¬ CNS Îµ-greedy: Exploration triggered');
799	            return exploredModel;
800	        }
801	
802	        for (const m of sorted) {
803	            // Sovereign FinOps: Skip exhausted cloud providers
804	            if (this.quotaTracker && this.isCloudModel(m)) {
805	                const provider = this.detectProvider(m);
806	                if (provider && this.quotaTracker.isProviderExhausted(provider)) {
807	                    logger.debug({ model: m, provider }, 'Skipping model: provider quota exhausted');
808	                    continue;
809	                }
810	            }
811	
812	            // Phase 8: Modality Check
813	            if (!this.isModalityCompatible(m, taskType)) {
814	                continue;
815	            }
816	
817	            if (this.isModelAvailableAndHealthy(m)) {
818	                // Phase 2: Latency Check for Fast Path
819	                if (preferred === this.config.fastPathModel && this.rolodex) {
820	                    const modelStats = this.rolodex.getAllModels().find(rm => rm.id === m || `ollama:${rm.id}` === m);
821	                    if (modelStats && modelStats.avgLatencyMs > 10000) {
822	                        logger.debug({ model: m }, 'Skipping model for fast path: high latency');
823	                        continue;
824	                    }
825	                }
826	                return m;
827	            }
828	            // Cloud models are assumed available unless explicitly marked failing
829	            if (this.isCloudModel(m) && !this.isModelFailing(m)) return m;
830	        }
831	        return this.config.localFallbackModel;
832	    }
