834	    /** Phase 8: Verify model supports the requested modality */
835	    private isModalityCompatible(modelId: string, taskType: TaskType): boolean {
836	        if (!this.rolodex) return true; // Can't verify without rolodex
837	
838	        const allModels = this.rolodex.getAllModels();
839	        // Phase 8.2: Flexible matching to handle version tags like :latest
840	        const model = allModels.find(m => {
841	            const normalizedMId = m.id.split(':')[0];
842	            const normalizedModelId = modelId.includes(':') ? modelId.split(':')[1] : modelId;
843	            const pureTarget = normalizedModelId.split(':')[0];
844	            
845	            return m.id === modelId || 
846	                   `${m.provider}:${m.id}` === modelId || 
847	                   (m.provider === 'ollama' && (modelId === m.id || pureTarget === normalizedMId));
848	        });
849	        
850	        if (!model) return true; // Unknown model - assume compatible (whitelist strategy)
851	
852	        if (taskType === 'vision' && !model.isVision) return false;
853	        if (taskType === 'embedding' && !model.isEmbedding) return false;
854	        if (taskType === 'image' && !model.isVision) return false; // Image tasks usually need vision or specialized flags
855	        if (taskType === 'text' && !model.isText) return false;
856	
857	        return true;
858	    }
