860	    private isModelAvailableAndHealthy(model: string): boolean {
861	        // Phase 8.2: Normalize for failure lookup (remove version tags)
862	        const pureModel = model.split(':')[0];
863	        
864	        if (this.isModelFailing(model) || this.isModelFailing(pureModel)) return false;
865	
866	        // Strict local check - must exist in Ollama output
867	        if (this.availableLocalModels.has(model)) return true;
868	        
869	        const match = Array.from(this.availableLocalModels).find(m => m === model || m.split(':')[0] === pureModel);
870	        return !!match;
871	    }
