987	    /**
988	     * Derive the organism's CURRENT state from hexagram lines.
989	     * Dominant YaoState across all 6 lines determines the organism's posture.
990	     * Old states = moving/changing, Young states = stable/holding.
991	     */
992	    private deriveOrganismState(lines: ContextCard[]): YaoState {
993	        if (lines.length === 0) return YaoState.YoungYang;
994	
995	        const counts = new Map<YaoState, number>();
996	        for (const line of lines) {
997	            const state = line.state ?? YaoState.YoungYang;
998	            counts.set(state, (counts.get(state) || 0) + 1);
999	        }
1000	
1001	        // Find dominant state
1002	        let dominant = YaoState.YoungYang;
1003	        let maxCount = 0;
1004	        for (const [state, count] of counts) {
1005	            if (count > maxCount) {
1006	                maxCount = count;
1007	                dominant = state;
1008	            }
1009	        }
1010	        return dominant;
1011	    }
1012	
1013	    /**
1014	     * Derive the INTENT state from ternary signals.
1015	     * Synthesizes local availability, history, and architecture alignment
1016	     * into a single YaoState representing where the organism WANTS to go.
1017	     */
1018	    private deriveIntentState(
1019	        localAvailability: YaoState,
1020	        historySignal: YaoState,
1021	        architectureAlignment: YaoState
1022	    ): YaoState {
1023	        // Score each signal: OldYang(+2), YoungYang(+1), YoungYin(0), OldYin(-1)
1024	        const scoreMap: Record<number, number> = {
1025	            [YaoState.OldYang]: 2,
1026	            [YaoState.YoungYang]: 1,
1027	            [YaoState.YoungYin]: 0,
1028	            [YaoState.OldYin]: -1,
1029	            // [YaoState.YangYao]: 1.5, // Duplicate with YoungYang
1030	            // [YaoState.YinYao]: -0.5  // Duplicate with YoungYin
1031	        };
1032	
1033	        const signals = [localAvailability, historySignal, architectureAlignment];
1034	        const total = signals.reduce((sum, s) => sum + (scoreMap[s] ?? 0), 0);
1035	
1036	        if (total >= 5) return YaoState.OldYang;       // All escalating
1037	        if (total >= 2) return YaoState.YoungYang;     // Mostly positive
1038	        if (total >= 0) return YaoState.YoungYin;      // Mostly passive
1039	        return YaoState.OldYin;                        // All failing
1040	    }
1041	
1042	    /**
1043	     * Derive history signal from model failure tracking.
1044	     * Many failures = retreat (OldYin), no failures = execute (YoungYang).
1045	     */
1046	    private deriveHistorySignal(): YaoState {
1047	        const totalFailures = Array.from(this.modelFailures.values()).reduce((s, v) => s + v, 0);
1048	        if (totalFailures === 0) return YaoState.YoungYang;  // Clean record
1049	        if (totalFailures <= 2) return YaoState.YoungYin;    // Minor issues
1050	        if (totalFailures <= 5) return YaoState.OldYang;     // Escalation needed
1051	        return YaoState.OldYin;                               // Critical retreat
1052	    }
1053	
1054	    /**
1055	     * Record a decision audit for organismal learning.
1056	     */
1057	    private recordDecisionAudit(audit: DecisionAuditRecord): void {
1058	        this.decisionHistory.push(audit);
1059	        // Keep last 100 decisions in memory
1060	        if (this.decisionHistory.length > 100) {
1061	            this.decisionHistory.shift();
1062	        }
1063	        logger.info({
1064	            model: audit.selectedModel,
1065	            directive: audit.directive,
1066	            hexagram: audit.hexagram,
1067	            latencyMs: audit.latencyMs,
1068	            fallbackUsed: audit.fallbackUsed
1069	        }, 'FPRAG: Decision audit recorded');
1070	
1071	        // Pipe to TrainingCollector for D:\ persistence
1072	        if (this.trainingCollector) {
1073	            this.trainingCollector.recordFPRAGDecision(audit).catch(() => { /* non-blocking */ });
1074	        }
1075	    }
