6	const logger = createLogger('VibeMapper');
7	
8	export type AgentVibe = 'SPOOKY' | 'MECHANICAL' | 'SERENE';
9	
10	/**
11	 * VibeMapper
12	 * Bridges the gap between mechanical fragment logic and agent personality states.
13	 * Deterministically derives the 'vibe' from MapZone metadata and MechanicalScarcity.
14	 */
15	export class VibeMapper {
16	    private static instance: VibeMapper;
17	    private currentVibe: AgentVibe = 'SERENE';
18	
19	    private constructor() {}
20	
21	    public static getInstance(): VibeMapper {
22	        if (!VibeMapper.instance) {
23	            VibeMapper.instance = new VibeMapper();
24	        }
25	        return VibeMapper.instance;
26	    }
27	
28	    /**
29	     * updateVibe - Recalculates the environmental vibe based on fragment logic density.
30	     * @param logic The authoritative fragment logic from RegistryB.
31	     */
32	    public updateVibe(logic: FragmentLogic): void {
33	        const hexManager = HexagramManager.getInstance();
34	        const registry = RegistryB.getInstance();
35	
36	        // 1. Somatic Input: Push intents from major entities into the hexagram
37	        // We look at the first few NPCs and Objects to avoid overloading the 6-line buffer
38	        const entities = [
39	            ...logic.npcs.slice(0, 2).map(id => ({ type: 'npcs' as const, id })),
40	            ...logic.objects.slice(0, 2).map(id => ({ type: 'objects' as const, id }))
41	        ];
42	
43	        for (const entity of entities) {
44	            const intent = registry.getIntent(entity.type, entity.id);
45	            if (intent) {
46	                // Map intent to a likely YaoState (Simplified heuristic)
47	                const state = intent.toLowerCase().includes('weapon') || intent.toLowerCase().includes('attack') 
48	                    ? 4 // OldYang (Radical Expansion/Conflict)
49	                    : (intent.toLowerCase().includes('legendary') ? 6 : 1); // YoungMixed or YoungYang
50	
51	                hexManager.pushLine({
52	                    lineIndex: 0, // Automatically handled by pushLine shifting
53	                    title: `Somatic Intent: ${entity.type} ${entity.id}`,
54	                    content: intent.substring(0, 100),
55	                    state: state as any,
56	                    importance: 1
57	                });
58	            }
59	        }
60	
61	        // 2. Derive Vibe from Emotional Pool
62	        const pool = hexManager.getEmotionalPool();
63	        const emotion = hexManager.getEmotionalState();
64	        
65	        let newVibe: AgentVibe = 'SERENE';
66	
67	        // Spooky: Agitated, Melancholy, or explicit Spooky triggers
68	        if (pool['Agitated'] > 0.5 || pool['Melancholy'] > 0.5) {
69	            newVibe = 'SPOOKY';
70	        }
71	        // Mechanical: Curious, Excited, or high rule density
72	        else if (pool['Curious'] > 0.5 || pool['Excited'] > 0.5 || (logic.rules?.length || 0) > 3) {
73	            newVibe = 'MECHANICAL';
74	        }
75	        else {
76	            newVibe = 'SERENE';
77	        }
78	
79	        if (newVibe !== this.currentVibe) {
80	            logger.info({ 
81	                anchor: logic.anchor, 
82	                old: this.currentVibe, 
83	                new: newVibe,
84	                emotion,
85	                ruleCount: logic.rules?.length 
86	            }, 'Neurological Vibe Transition.');
87	            this.currentVibe = newVibe;
88	        }
89	    }
90	
91	    public getVibe(): AgentVibe {
92	        return this.currentVibe;
93	    }
94	}
