1	/**
2	 * StateManager â€” Sovereign process state tracking.
3	 * Persistent metrics and session-level state for the ternary engine.
4	 */
5	
6	export interface Metrics {
7	    turnCount: number;
8	    tokensTotal: number;
9	    latencyAvg: number;
10	    successRate: number;
11	}
12	
13	export interface SovereignState {
14	    mode: 'sovereign' | 'hybrid' | 'local';
15	    selectedWorkspace?: string;
16	    metrics: Metrics;
17	    lastError?: string;
18	    sessionId: string;
19	}
20	
21	export class StateManager {
22	    private static instance: StateManager;
23	    private state: SovereignState;
24	
25	    private constructor() {
26	        this.state = {
27	            mode: 'hybrid',
28	            sessionId: `session-${Date.now()}-${Math.random().toString(36).substring(7)}`,
29	            metrics: {
30	                turnCount: 0,
31	                tokensTotal: 0,
32	                latencyAvg: 0,
33	                successRate: 1.0
34	            }
35	        };
36	    }
37	
38	    public static getInstance(): StateManager {
39	        if (!StateManager.instance) {
40	            StateManager.instance = new StateManager();
41	        }
42	        return StateManager.instance;
43	    }
44	
45	    public getState(): SovereignState {
46	        return { ...this.state };
47	    }
48	
49	    public getSessionId(): string {
50	        return this.state.sessionId;
51	    }
52	
53	    public updateMetrics(delta: Partial<Metrics>): void {
54	        this.state.metrics = {
55	            ...this.state.metrics,
56	            turnCount: this.state.metrics.turnCount + (delta.turnCount ?? 0),
57	            tokensTotal: this.state.metrics.tokensTotal + (delta.tokensTotal ?? 0)
58	        };
59	    }
60	
61	    public setMode(mode: SovereignState['mode']): void {
62	        this.state.mode = mode;
63	    }
64	
65	    public setWorkspace(path: string): void {
66	        this.state.selectedWorkspace = path;
67	    }
68	}
